package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.util.*;
public class ConnectProtocolTest {
 @Test public void pairingIsVersionedAndOnlyPrivateIpv4()throws Exception{ConnectProtocol.Pair p=new ConnectProtocol.Pair("192.168.1.20",34567,ConnectProtocol.secret(),ConnectProtocol.secret());assertEquals(p.token,ConnectProtocol.Pair.parse(p.code()).token);for(String host:new String[]{"8.8.8.8","127.0.0.1","169.254.1.2","example.com","192.168.1.999","172.32.0.1"})try{ConnectProtocol.Pair.parse(new ConnectProtocol.Pair(host,34567,p.token,p.pin).code());fail(host);}catch(IOException expected){}assertTrue(ConnectProtocol.privateHost("172.16.0.1"));assertTrue(ConnectProtocol.privateHost("10.0.0.1"));try{ConnectProtocol.Pair.parse(p.code()+"?redirect=http://example.com");fail();}catch(IOException expected){}}
 @Test public void manifestsNeedCorrectTokenAndValidMedia()throws Exception{String secret=ConnectProtocol.secret();ByteArrayOutputStream bytes=new ByteArrayOutputStream();ConnectProtocol.offer(new DataOutputStream(bytes),secret,Arrays.asList(new ConnectProtocol.FileInfo("Aula.pdf","application/pdf",123)));assertEquals(123,ConnectProtocol.offer(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())),secret).get(0).size);try{ConnectProtocol.offer(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())),ConnectProtocol.secret());fail();}catch(IOException expected){}for(String mime:new String[]{"application/vnd.android.package-archive","text/plain","application/octet-stream"})try{new ConnectProtocol.FileInfo("Aula",mime,1);fail();}catch(IOException expected){}}
 @Test public void quantitiesAndSizesAreBounded()throws Exception{List<ConnectProtocol.FileInfo> list=new ArrayList<>();for(int i=0;i<11;i++)list.add(new ConnectProtocol.FileInfo("Aula.pdf","application/pdf",1));try{ConnectProtocol.total(list);fail();}catch(IOException expected){}try{new ConnectProtocol.FileInfo("Aula.pdf","application/pdf",-1);fail();}catch(IOException expected){}try{new ConnectProtocol.FileInfo("Aula.pdf","application/pdf",ConnectProtocol.FILE_LIMIT+1);fail();}catch(IOException expected){}list=Arrays.asList(new ConnectProtocol.FileInfo("A","audio/mpeg",ConnectProtocol.FILE_LIMIT),new ConnectProtocol.FileInfo("B","audio/mpeg",ConnectProtocol.FILE_LIMIT),new ConnectProtocol.FileInfo("C","audio/mpeg",1));try{ConnectProtocol.total(list);fail();}catch(IOException expected){}}
 @Test public void namesCannotBecomePaths()throws Exception{String name=ConnectProtocol.safeName("../../outside\u0000.mp3");assertFalse(name.contains("/"));assertFalse(name.contains("\\"));assertFalse(name.contains("\u0000"));assertFalse(name.startsWith("."));assertEquals("Aula.pdf",ConnectProtocol.safeName(" Aula.pdf "));}
 @Test public void exactBytesAndDigestAndTruncation()throws Exception{byte[] input=new byte[200000];new Random(42).nextBytes(input);ByteArrayOutputStream output=new ByteArrayOutputStream();long[] count={0};byte[] hash=ConnectProtocol.copy(new ByteArrayInputStream(input),output,input.length,n->count[0]+=n);assertArrayEquals(input,output.toByteArray());assertArrayEquals(java.security.MessageDigest.getInstance("SHA-256").digest(input),hash);assertEquals(input.length,count[0]);try{ConnectProtocol.copy(new ByteArrayInputStream(input),new ByteArrayOutputStream(),input.length+1,n->{});fail();}catch(EOFException expected){}}
 @Test public void cancellationStopsBeforeNextWrite()throws Exception{try{Thread.currentThread().interrupt();try{ConnectProtocol.copy(new ByteArrayInputStream(new byte[100]),new ByteArrayOutputStream(),100,n->{});fail();}catch(InterruptedIOException expected){}}finally{Thread.interrupted();}}
}
